### C++

```cpp
#include <iostream>
#include <vector>
#include <stack>
using namespace std;

// 使用 DFS 统计一个等价类的大小
int dfs(int start, const vector<vector<int>>& a, vector<bool>& vis, int n) {
    stack<int> st;
    st.push(start);
    vis[start] = true;
    int cnt = 0;

    while (!st.empty()) {
        int u = st.top();
        st.pop();
        cnt++;

        // 枚举所有样本，找与当前样本同频的点
        for (int v = 0; v < n; v++) {
            if (a[u][v] == 1 && !vis[v]) {
                vis[v] = true;
                st.push(v);
            }
        }
    }

    return cnt;
}

// 求解零频样本数量的最小值和最大值
pair<int, int> solve(int n, const vector<vector<int>>& a) {
    vector<bool> vis(n, false);
    int mn = n;
    int mx = 1;

    // 枚举每个等价类
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            int size = dfs(i, a, vis, n);
            mn = min(mn, size);
            mx = max(mx, size);
        }
    }

    return {mn, mx};
}

int main() {
    int n;
    cin >> n;
    vector<vector<int>> a(n, vector<int>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> a[i][j];
        }
    }

    pair<int, int> ans = solve(n, a);

    cout << ans.first << " " << ans.second << endl;

    return 0;
}
